#include "ksStateStorageTask.h"
#include <iostream>
#include <vector>
#include <utility>
#include <stdexcept>
using T=ks::StateStorageTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned k=0;k<6;++k)for(unsigned p=0;p<256;++p)for(unsigned v=0;v<256;++v){T task(T::Kind(k),p);unsigned reads=0,clocks=0,children=0;std::vector<std::pair<T::Write,uint32_t>> writes;auto read=[&](T::Read r)->unsigned{++reads;return r==T::Read::Mode||r==T::Read::Dirty?v:p;};auto write=[&](T::Write w,uint32_t value){writes.emplace_back(w,value);};while(!task.complete()){if(task.awaitingPart()){check(task.part()==p,"Part child input differs");++children;check(task.resumePart(),"Part child rejected");continue;}const auto c=task.nextClocks(),before=reads;const auto stores=writes.size();check(!task.advanceBefore(c-1,read,write)&&reads==before&&writes.size()==stores,"Storage early observation");check(task.advanceBefore(c,read,write)==c,"Storage admission differs");clocks+=c;}
 std::vector<std::pair<T::Write,uint32_t>> expected;unsigned expectedClocks=0,expectedReads=0;if(k==0){expectedClocks=v?64:32;expectedReads=v?2:1;check(children==unsigned(v!=0),"Storage child count");}else if(k==1){expectedClocks=106;expected={{T::Write::CurrentBase,0x168fc+p*256},{T::Write::LiveBase,0x16e12+p*256}};check(task.address()==0x168fc+p*256,"Current address differs");}else if(k==2){expectedClocks=70;expectedReads=1;check(task.address()==0x845800+p*1024,"Multi bank address differs");}else if(k==3){expectedClocks=56;expectedReads=2;expected={{T::Write::Dirty,v|(1u<<(p&7))}};}else{expectedClocks=98;expected=k==4?std::vector<std::pair<T::Write,uint32_t>>{{T::Write::FieldTable,0x11210},{T::Write::LimitTable,0x112db},{T::Write::DisplayTable,0x1142c}}:std::vector<std::pair<T::Write,uint32_t>>{{T::Write::FieldTable,0x11143},{T::Write::LimitTable,0x11299},{T::Write::DisplayTable,0x1141f}};}
 if(clocks!=expectedClocks){std::cerr<<"kind="<<k<<" clocks="<<clocks<<" expected="<<expectedClocks<<'\n';throw std::runtime_error("Storage clocks differ");}check(reads==expectedReads&&writes==expected&&!task.resumePart(),"Storage outcome/order differs");++cases;}
 std::cout<<"PASS: "<<cases<<" complete storage jobs/all6kinds,all byte parts/banks/dirty masks/modes,base addresses,ordered stores/child,exact clocks/deadlines\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
